//! Parts regenerated by workers the engine cannot wait for (OVERHAUL_PLAN W1b: the browser's
//! geometry host workers).
//!
//! `oc_asm`'s [`Runner`] is called in the middle of a request and must return the parts'
//! results; natively it blocks while host processes work. The browser's engine worker is one
//! thread without shared memory (W1 design point 1), so it cannot block on other workers. So
//! the request is **deferred** instead: when the runner is asked for parts that are not ready,
//! it records them and unwinds the request with [`Deferred`] (no reply, nothing kept). The
//! worker regenerates those parts on its host workers, hands their results over
//! ([`Prepared::prepare`]) and runs the same request again; this time the runner returns them
//! and the request completes exactly as it would natively.
//!
//! This relies on `oc_asm` calling its runner before a request changes anything the second run
//! would see differently: `Assembler::build` calls it after its planning pass and before the
//! build, `resolve_many` before it resolves anything (tested in `tests/hosts.rs`). The engine
//! (`Engine::run`) drops a deferred request without clearing its caches.
//!
//! What crosses to a host worker is `oc_host::proto`'s data (a Job; a Done or Failed reply),
//! not its pipes. A host worker that trapped, aborted or did not answer in time fails only its
//! part, with the native host pool's messages ([`DIED`], [`TIMED_OUT`]).
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;
use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::time::Duration;

use oc_asm::parallel::{PartJob, PartOut, Runner};
use oc_host::proto;
use oc_host::HostStats;
use oc_naming::Rules;

/// The panic payload that unwinds a deferred request (with `resume_unwind`: no panic message).
pub struct Deferred;

/// How a part came back from a host worker ([`Prepared::prepare`]): `proto::DONE` and
/// `proto::FAILED` carry the host's reply; these two are the worker's own news.
/// The host worker trapped or aborted while regenerating the part (no payload).
pub const DIED: u32 = 0x101;
/// The host worker did not answer in time and was stopped (payload: seconds, `f64` LE).
pub const TIMED_OUT: u32 = 0x102;

type Key = (String, u64);

fn key(j: &PartJob) -> Key {
    (j.hash.clone(), j.quality.to_bits())
}

#[derive(Default)]
struct State {
    /// Results handed over, by part hash and quality.
    ready: HashMap<Key, Result<PartOut, String>>,
    /// The parts the last deferred request asked for (index = the job id sent).
    wanted: Vec<PartJob>,
    rules: Rules,
    /// How many host workers there are (the build statistics' `workers`).
    width: usize,
    /// False: parts not ready are regenerated by the engine itself (`Err` to the assembler).
    defer: bool,
    /// The assembler asked for the hosts to be started (`Runner::warm`).
    warm: bool,
}

/// The engine side of the browser's host workers: an [`oc_asm::parallel::Runner`] (install it
/// as the assembler's runner) and the handle the worker hands results to; clones share state.
#[derive(Clone)]
pub struct Prepared {
    state: Rc<RefCell<State>>,
    stats: Arc<HostStats>,
}

impl Prepared {
    /// For `width` host workers.
    pub fn new(width: usize) -> Prepared {
        let state = State { width: width.max(1), defer: true, ..State::default() };
        Prepared { state: Rc::new(RefCell::new(state)), stats: Arc::new(HostStats::default()) }
    }

    /// The counts reported with every assembly build (`hosts` in its reply, as natively).
    pub fn stats(&self) -> Arc<HostStats> {
        self.stats.clone()
    }

    /// A host worker was started (or started again after it died).
    pub fn started(&self) {
        self.stats.started.fetch_add(1, Ordering::Relaxed);
    }

    /// Whether requests are deferred when parts are not ready (default true). Off, such
    /// parts are regenerated by the engine itself, one by one.
    pub fn set_defer(&self, on: bool) {
        self.state.borrow_mut().defer = on;
    }

    /// The parts the deferred request needs, as `oc_host::proto` jobs whose ids are their
    /// indices. Parts whose documents cannot be written are failed at once (the engine
    /// regenerates them itself, as with a host that cannot start).
    pub fn wanted(&self) -> Vec<Vec<u8>> {
        let mut s = self.state.borrow_mut();
        let rules = s.rules;
        let wanted = s.wanted.clone();
        let mut out = Vec::with_capacity(wanted.len());
        for (i, j) in wanted.iter().enumerate() {
            match oc_doc::save(&j.doc) {
                Ok(doc) => out.push(proto::encode_job(&proto::Job { id: i as u64, quality: j.quality, rules, doc })),
                Err(e) => {
                    s.ready.insert(key(j), Err(e.to_string()));
                    out.push(vec![]);
                }
            }
        }
        out
    }

    /// Hands over wanted part `id`'s result: `kind` is `proto::DONE` or `proto::FAILED` with
    /// the host's payload, or [`DIED`] or [`TIMED_OUT`].
    pub fn prepare(&self, id: u64, kind: u32, payload: &[u8]) -> Result<(), String> {
        let mut s = self.state.borrow_mut();
        let job = s.wanted.get(id as usize).cloned().ok_or_else(|| format!("no part {id} is wanted"))?;
        let r = match kind {
            proto::DONE => {
                let (got, out) = proto::decode_done(payload)?;
                if got != id {
                    return Err(format!("reply {got} for part {id}"));
                }
                Ok(out)
            }
            proto::FAILED => Err(proto::decode_failed(payload)?.1),
            DIED => {
                self.stats.died.fetch_add(1, Ordering::Relaxed);
                Ok(PartOut::failed(oc_host::pool::DIED))
            }
            TIMED_OUT => {
                self.stats.timed_out.fetch_add(1, Ordering::Relaxed);
                let secs = payload.get(..8).and_then(|b| b.try_into().ok()).map(f64::from_le_bytes).unwrap_or(0.0);
                Ok(PartOut::failed(oc_host::pool::timed_out(Duration::from_secs_f64(secs.max(0.0)))))
            }
            k => return Err(format!("unknown part reply {k}")),
        };
        s.ready.insert(key(&job), r);
        Ok(())
    }

    /// After a request that completed: results it did not use are dropped.
    pub fn finish(&self) {
        let mut s = self.state.borrow_mut();
        s.ready.clear();
        s.wanted.clear();
    }

    /// Whether the assembler asked for the host workers to be started since the last call.
    pub fn take_warm(&self) -> bool {
        std::mem::take(&mut self.state.borrow_mut().warm)
    }
}

impl Runner for Prepared {
    fn width(&self, jobs: usize) -> usize {
        self.state.borrow().width.min(jobs).max(1)
    }

    fn run(&mut self, rules: Rules, jobs: &[PartJob]) -> Vec<Result<PartOut, String>> {
        let mut s = self.state.borrow_mut();
        let missing: Vec<PartJob> = jobs.iter().filter(|j| !s.ready.contains_key(&key(j))).cloned().collect();
        if !missing.is_empty() && s.defer {
            s.wanted = missing;
            s.rules = rules;
            drop(s);
            std::panic::resume_unwind(Box::new(Deferred));
        }
        jobs.iter().map(|j| s.ready.remove(&key(j)).unwrap_or_else(|| Err("not regenerated on a host worker".into()))).collect()
    }

    fn warm(&mut self) {
        self.state.borrow_mut().warm = true;
    }
}
